from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

from flint import acb, arb, fmpz_poly


class AlgRecognizeError(Exception):
    """Base class for package-specific errors."""


class NoRelationFound(AlgRecognizeError, ValueError):
    """No sufficiently convincing algebraic relation was found."""


class InsufficientAccuracyError(NoRelationFound):
    """The input does not contain enough trustworthy numerical information."""


class SearchLimitError(AlgRecognizeError, ValueError):
    """The requested search exceeds the package's default safety limit."""


Confidence = Literal["exact", "certified", "high_confidence"]


@dataclass(frozen=True)
class AlgRecognizeResult:
    """Result returned by :func:`algrecognize.algrecognize`.

    ``certified`` has a deliberately narrow meaning: the supplied Acb ball
    overlaps exactly one certified root enclosure of the selected irreducible
    polynomial. It does not prove that an arbitrary numerical approximation
    was originally generated from that algebraic number.

    ``relation_score_bits`` is a conservative lower bound on

        -log2(|p(x)| / (H(p) max(1, |x|)^deg(p))),

    where H(p) is the coefficient height. Larger values indicate a more
    striking numerical relation.

    For exact rational inputs, ``input_accuracy_bits`` is ``None``,
    ``confidence`` is ``"exact"``, and no LLL search is performed.
    """

    polynomial: fmpz_poly
    relation_polynomial: fmpz_poly
    matched_root: acb
    root_distance_upper: arb
    residual: acb
    relation_score_bits: arb
    acceptance_threshold_bits: int
    input_accuracy_bits: int | None
    input_is_exact: bool
    degree_searched: int
    polynomial_height: int
    scale_bits: int
    magnitude_exponent_bits: int
    lattice_vector: tuple[int, ...]
    certified: bool
    confidence: Confidence
    reciprocal_normalization_used: bool
